Fix this code that failed with: [line 2] Expected ';'

Input: fn bubble_sort(arr) {
    let n = arr.length
    for (let i = 0; i < n - 1; i++) {
        for (let j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                let temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
    return arr;
}

let arr = [64, 34, 25, 12, 22, 11, 90, 1, 45, 78];
bubble_sort(arr);
print(arr.join(" "));
,"The semicolon is required after the statement. Here's the corrected code:

